// P21 adversarial review verifier - session S55. Independent of the lab engine:
// hits are generated by a different closed form, tree choices are decided by
// brute-force counts (no crowd-point logic), EVT/IVT numbers are re-derived by
// Newton's method and exact fraction arithmetic. Poisons and prose needles included.
var VPASS, VFAILS, VREP;
function vck(name, ok) { if (ok) VPASS++; else { VFAILS++; VREP.push("FAIL " + name); } }
function pieceVA() { // independent card + both machines
  VPASS=0; VFAILS=0; VREP=[];
  // independent hit form: odd -> (2n+5)/(6n+6), even -> (4n+1)/(6n+6)
  var hit2=function(n){ return (n%2===1) ? (2*n+5)/(6*n+6) : (4*n+1)/(6*n+6); };
  var card=["0.583333","0.500000","0.458333","0.566667","0.416667","0.595238","0.395833","0.611111","0.383333","0.621212","0.375000","0.628205","0.369048","0.633333","0.364583","0.637255"];
  var ok=true; for (var n=1;n<=16;n++) if (hit2(n).toFixed(6)!==card[n-1]) ok=false;
  vck("card-via-independent-form", ok);
  // brute counts decide halves: a half is "endless" if it holds >= 500 of the first 20000
  var count=function(lo,hi){ var c=0; for (var n=1;n<=20000;n++){ var v=hit2(n); if (v>=lo&&v<=hi)c++; } return c; };
  var endless=function(lo,hi){ return count(lo,hi)>=500; };
  // left machine, tie -> left
  var lo=0, hi=1, seq=[];
  for (var d=0; d<6; d++) {
    var m=(lo+hi)/2, li=endless(lo,m), ri=endless(m,hi);
    if (li&&ri) { hi=m; seq.push("tL"); } else if (li) { hi=m; seq.push("L"); } else { lo=m; seq.push("R"); }
  }
  vck("left-tree-via-brute", seq.join("")==="tLRLRLR" && Math.abs(hi-11/32)<1e-12 && Math.abs(lo-21/64)<1e-12);
  vck("left-tree-catch-contains-1/3", lo<=1/3 && 1/3<=hi);
  var lo2=0, hi2=1, seq2=[];
  for (d=0; d<6; d++) {
    var m2=(lo2+hi2)/2, li2=endless(lo2,m2), ri2=endless(m2,hi2);
    if (li2&&ri2) { lo2=m2; seq2.push("tR"); } else if (ri2) { lo2=m2; seq2.push("R"); } else { hi2=m2; seq2.push("L"); }
  }
  vck("right-tree-via-brute", seq2.join("")==="tRLRLRL" && Math.abs(hi2-43/64)<1e-12 && Math.abs(lo2-21/32)<1e-12);
  vck("right-tree-catch-contains-2/3", lo2<=2/3 && 2/3<=hi2);
  vck("right-tree-width-1/64", Math.abs((hi2-lo2)-1/64)<1e-12);
  // annotation counts by brute
  vck("ann-D3right-6", count(3/8,1/2)===6);
  vck("ann-D5right-19", count(11/32,3/8)===19);
  vck("ann-D2left-0", count(0,1/4)===0);
  vck("ann-D4left-0", count(1/4,5/16)===0);
  vck("ann-D6left-0", count(5/16,21/64)===0);
  vck("ann-rtree-D2right-0", count(3/4,1)===0);
  return "pieceVA "+VPASS+" pass "+VFAILS+" fail "+VREP.join("; ");
}
function pieceVB() { // EVT + IVT by independent methods: Newton, exact fractions
  VPASS=0; VFAILS=0; VREP=[];
  var f=function(x){ return Math.sin(x)+Math.sin(Math.SQRT2*x); };
  var d1f=function(x){ return Math.cos(x)+Math.SQRT2*Math.cos(Math.SQRT2*x); };
  var d2f=function(x){ return -Math.sin(x)-2*Math.sin(Math.SQRT2*x); };
  // Newton on f' from 1.3 -> x*
  var x=1.3;
  for (var i=0;i<40;i++){ x = x - d1f(x)/d2f(x); }
  vck("xstar-via-newton", x.toFixed(10)==="1.2632578175");
  vck("fxstar-via-newton", f(x).toFixed(9)==="1.929904111");
  // decoy and runner-up independently: critical points via Newton from 6.2 and 9.5
  var x1=6.2; for (i=0;i<60;i++){ x1 = x1 - d1f(x1)/d2f(x1); }
  var x2=9.5; for (i=0;i<60;i++){ x2 = x2 - d1f(x2)/d2f(x2); }
  vck("decoy-via-newton", x1.toFixed(3)==="6.097" && f(x1).toFixed(6)==="0.533858");
  vck("runnerup-via-newton", x2.toFixed(3)==="9.441" && f(x2).toFixed(6)==="0.690759");
  vck("gaps-via-newton", (f(x)-f(x2)).toFixed(6)==="1.239145" && (f(x)-f(x1)).toFixed(6)==="1.396047");
  // IVT bisection table by EXACT FRACTIONS (num/den integers, no floating point)
  var frac=function(n,d){ return {"n":n,"d":d}; };
  var fval=function(m){ return m.n*m.n*m.n/(m.d*m.d*m.d) - m.n/m.d - 1; }; // returns float, but from exact dyadic mid
  var mids=[frac(3,2),frac(5,4),frac(11,8),frac(21,16),frac(43,32),frac(85,64)];
  var vals=[7/8,-19/64,115/512,-211/4096,2707/32768,3821/262144];
  var ok=true;
  for (var k=0;k<6;k++){ if (Math.abs(fval(mids[k])-vals[k])>1e-15) ok=false; }
  vck("bisection-fractions-exact", ok);
  vck("bisection-print-6dp", [ (7/8).toFixed(6)==="0.875000", (-19/64).toFixed(6)==="-0.296875", (115/512).toFixed(6)==="0.224609", (-211/4096).toFixed(6)==="-0.051514", (2707/32768).toFixed(6)==="0.082611", (3821/262144).toFixed(6)==="0.014576" ].every(Boolean));
  // rho by Newton on x^3-x-1 from 1.5
  var r=1.5;
  for (i=0;i<30;i++){ r = r - (r*r*r-r-1)/(3*r*r-1); }
  vck("rho-via-newton", r.toFixed(10)==="1.3247179572");
  vck("rho3-check", (r*r*r).toFixed(10)==="2.3247179572" && (r+1).toFixed(10)==="2.3247179572");
  vck("walls-40-and-34", Math.pow(2,-40).toExponential(1)==="9.1e-13" && Math.round(10/Math.pow(2,34)*1e10)===6);
  return "pieceVB "+VPASS+" pass "+VFAILS+" fail "+VREP.join("; ");
}
function pieceVC() { // poisons: each poisoned claim must be REJECTED
  VPASS=0; VFAILS=0; VREP=[];
  var hit2=function(n){ return (n%2===1) ? (2*n+5)/(6*n+6) : (4*n+1)/(6*n+6); };
  // poison 1: doctored card (hits 7 and 9 swapped)
  var poisoned=["0.583333","0.500000","0.458333","0.566667","0.416667","0.595238","0.383333","0.611111","0.395833","0.621212","0.375000","0.628205","0.369048","0.633333","0.364583","0.637255"];
  var detect1=false; for (var n=1;n<=16;n++) if (hit2(n).toFixed(6)!==poisoned[n-1]) detect1=true;
  vck("poison-doctored-card-detected", detect1);
  // poison 2: D5 right half holds "20 hits"
  var c=0; for (n=1;n<=20000;n++){ var v=hit2(n); if (v>=11/32&&v<=3/8)c++; }
  vck("poison-D5right-20-rejected", c!==20 && c===19);
  // poison 3: rho with last digit off
  var r=1.3247179572;
  vck("poison-rho-off-by-one-rejected", (1.3247179573).toFixed(10)!==r.toFixed(10));
  // poison 4: doctored f(x*) = 1.929904112
  var f=function(x){ return Math.sin(x)+Math.sin(Math.SQRT2*x); };
  vck("poison-fxstar-doctored-rejected", f(1.2632578175).toFixed(9)!=="1.929904112" && f(1.2632578175).toFixed(9)==="1.929904111");
  // poison 5: claim 1/2 is a limit point of the card (quiet window test)
  var quiet=0; for (n=1;n<=20000;n++){ var v2=hit2(n); if (Math.abs(v2-0.5)<1/12) quiet++; }
  vck("poison-half-as-crowd-rejected", quiet<500);
  // poison 6: exhibit A window holds "14 hits"
  var c6=0; for (n=1;n<=20000;n++){ var h=1/n; if (h>0.05&&h<0.15)c6++; }
  vck("poison-exA-14-rejected", c6!==14 && c6===13);
  // poison 7: b(10) claimed as 0.56
  var b=function(n){ return 1/2 + ((n%2===0)?1:-1)/(2*n); };
  vck("poison-b10-doctored-rejected", Math.abs(b(10)-0.55)<1e-12 && b(10)!==0.56);
  // poison 8: claimed catch "hit at 1/3" (the catch is never a hit)
  var isHit=false; for (n=1;n<=100000;n++) if (hit2(n)===1/3) isHit=true;
  vck("poison-catch-is-a-hit-rejected", !isHit);
  // poison 9: EVT claimed for the torn-tread g (Exhibit C) - maximizer exists
  var gg=function(x){ return x<0.5 ? x : 0; };
  var maxAt=-1; for (n=0;n<=100000;n++){ var x=n/100000; if (gg(x)>maxAt) maxAt=gg(x); }
  vck("poison-exC-maximizer-exists-rejected", maxAt<0.5);
  // poison 10: level-3 EVT choice claimed "left" (coin toss that the record decides)
  var scan=function(lo,hi){ var bb=-1e9; for(var x=lo;x<=hi+1e-15;x+=1e-6){ var val=f(x); if(val>bb)bb=val; } return bb; };
  vck("poison-L3-left-rejected", scan(1.25,2.5)>scan(0,1.25));
  return "pieceVC "+VPASS+" pass "+VFAILS+" fail "+VREP.join("; ");
}
function pieceVD(page) { // loader gates + prose needles on the page text
  VPASS=0; VFAILS=0; VREP=[];
  var has=function(s){ return page.indexOf(s)>=0; };
  // loader gates
  vck("gate-title", has('<title>P21 · Catch the limit point · The Patterns Atlas</title>'));
  vck("gate-mathjax-head", has("window.MathJax={tex:{inlineMath:[['\\\\(','\\\\)']],displayMath:[['\\\\[','\\\\]']]},svg:{fontCache:'global'}};"));
  vck("gate-stylesheet", has('<link rel="stylesheet" href="assets/style.css">'));
  vck("gate-close", has('</html>'));
  vck("gate-footer", has('<p>Return to the <a href="index.html">index</a> · Next: <a href="p22-fixed-point.html">P22 · Iterate to a fixed point</a></p>'));
  var count=function(re){ var m=page.match(re); return m?m.length:0; };
  vck("gate-h2-8", count(/<h2>/g)===8);
  vck("gate-h3-9", count(/<h3>/g)===9);
  vck("gate-boxes-3", count(/class="pattern-box"/g)===3);
  vck("gate-warn-1", count(/aside class="warn"/g)===1);
  vck("gate-onramp-1", count(/aside class="onramp"/g)===1);
  vck("gate-tables-4", count(/<table/g)===4);
  vck("gate-svg-3", count(/<svg/g)===3);
  vck("gate-details-10", count(/<details>/g)===10);
  vck("gate-pid-3", count(/class="pid"/g)===3);
  vck("gate-no-backtick", count(/`/g)===0);
  vck("gate-no-dollar", count(/\$/g)===0);
  vck("gate-no-todo", count(/TODO/g)===0);
  // prose needles (required strings)
  var needles=["the line has no holes","closed, bounded room","Bolzano","Weierstrass","Dedekind","Cantor","Heine","van der Laan","plastic constant","extreme value theorem","intermediate value theorem","limit point","nested intervals","subsequence","1.2632578175","1.929904111","1.3247179572","2.3247179572","0.533858","0.690759","1.239145","1.396047","a sixty-fourth of a metre wide","hit 10 landing exactly on the near wall","exactly 6 hits, then silence","exactly 19 hits, then silence","the endless pigeonhole","three-key signature","p22-fixed-point.html","p41-mountain-pass.html","p54-stable-compactification.html","p10-pigeonhole.html","p15-squeeze.html","p20-polynomial-identity.html","p17-duality.html"];
  var missing=[];
  for (var i=0;i<needles.length;i++) if (!has(needles[i])) missing.push(needles[i]);
  vck("prose-needles-all-present", missing.length===0);
  // moon set
  vck("gate-moons", has("●○○") && has("●●○") && has("●●●") && has("◆") && has("◐"));
  // pid lines reference P10/P15/P11/P05
  vck("gate-pid-refs", has("p11-contradiction.html") && has("p05-canonical-form.html"));
  return "pieceVD "+VPASS+" pass "+VFAILS+" fail "+(missing.length?"MISSING:"+missing.join(",")+"; ":"")+VREP.join("; ");
}
